const msg = $('Telegram Message').first().json.message || {};
const chat_id = msg.chat?.id != null ? String(msg.chat.id) : '';
const text = typeof msg.text === 'string' ? msg.text.trim() : '';
const first_name = msg.from?.first_name || '';
const records = $('Get Cached Records').all().map(i=>i.json).filter(r=>r.author==='thsottiaux' && r.record_key && /^https:\/\/(?:x\.com|twitter\.com)\/thsottiaux\/status\/\d+$/.test(r.url || ''));
const state = $('Get Sync State').all().map(i=>i.json).find(r=>r.state_key==='main') || {};
const esc = s=>String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const pt = value=>{
  const d=new Date(value); if(Number.isNaN(d.getTime()))return '';
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);
  const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day;
};
const today=pt(new Date());
const command=text.startsWith('/')?text.split(/\s+/)[0].split('@')[0].toLowerCase():'';
const arg=text.split(/\s+/).slice(1).join(' ').toLowerCase();
let route=chat_id && text?'reply':'ignore'; let reply=''; let alert_mode='all';
const help='Try /today for Tibo’s collected posts, /reset for the latest reset, or ask a question.\n/alerts all | improvements | resets | off';
const fresh=state.synced_at?'Last collection: '+String(state.synced_at)+' (Pacific day).':'Collection time unavailable.';
const coverage=state.last_status==='partial'?'Coverage is partial: '+String(state.last_error || 'some sources were unavailable').slice(0,220):'Public X collection can miss posts.';
const todays=[...new Map(records.filter(r=>r.record_type==='update' && pt(r.announced_at)===today).map(r=>[r.entry_id,r])).values()].sort((a,b)=>String(b.announced_at).localeCompare(String(a.announced_at)));
const todayRequest=command==='/today';
if(command==='/start' || command==='/subscribe'){
  route='subscribe';reply='You’re in. I’ll send confirmed resets and daily Codex improvements—no general tweet chatter.\n'+help+'\nhttps://tibo-news.vercel.app';
} else if(command==='/stop' || (command==='/alerts' && arg==='off')){
  route='unsubscribe';reply='Alerts are off. /subscribe turns them back on.';
} else if(command==='/alerts'){
  if(['all','improvements','resets'].includes(arg)){route='subscribe';alert_mode=arg;reply='Done. Your alerts: '+arg+'.';}
  else reply='Choose /alerts all, /alerts improvements, /alerts resets or /alerts off.';
} else if(todayRequest && arg && !/^[1-9]\d*$/.test(arg)){
  reply='Usage: /today or /today <positive page number>.';
} else if(todayRequest){
  const page=command==='/today'?Math.max(1,Math.floor(Number(arg)||1)):1;
  const start=(page-1)*5;const selected=todays.slice(start,start+5);
  reply='Tibo today ('+today+', Pacific): '+todays.length+' collected post'+(todays.length===1?'':'s')+'.\n';
  if(!todays.length) reply+='No posts collected for today yet. This doesn’t prove he hasn’t posted.\n';
  else if(!selected.length)reply+='That page is empty. Try /today.\n';
  else reply+=selected.map(r=>'• '+esc(String(r.summary || r.title).slice(0,360))+'\n'+esc(r.url)).join('\n\n')+'\n';
  if(todays.length>start+5)reply+='More: /today '+(page+1)+'\n';
  reply+=esc(fresh)+'\n'+esc(coverage);
} else if(command==='/reset'){
  const r=records.filter(r=>r.record_type==='reset').sort((a,b)=>String(b.announced_at).localeCompare(String(a.announced_at)))[0];
  reply=r?'Latest confirmed reset: '+esc(r.kind)+' on '+esc(r.announced_at)+'.\n'+esc(r.url)+'\n'+esc(fresh):'No confirmed reset cached yet.';
} else if(command==='/source'){
  reply='Challenge and resets: https://codex-resets.com/tibo-28\nAPI: https://codex-resets.com/api/docs\nCollected posts: https://x.com/thsottiaux\nDashboard: https://tibo-news.vercel.app';
} else if(command) reply=help;
else if(route!=='ignore'){
  route='question';
  const stop=new Set(['what','when','where','how','the','and','about','tibo','codex','did','has','this','that','please']);
  const words=text.toLowerCase().split(/\W+/).filter(w=>w.length>2 && !stop.has(w));
  const matches=records.map(r=>({r,score:words.filter(w=>(r.title+' '+r.summary).toLowerCase().includes(w)).length})).filter(x=>x.score).sort((a,b)=>b.score-a.score);
  const selected=[...new Map(matches.map(x=>[x.r.entry_id,x.r])).values()].slice(0,2);
  reply=selected.length?'Closest collected posts:\n'+selected.map(r=>esc(String(r.summary || r.title).slice(0,480))+'\n'+esc(r.url)).join('\n\n'):'I don’t have that in the collected posts. Try /today or /reset.';
}
const contextRecords=[...(todayRequest?todays:records)].sort((a,b)=>String(b.announced_at).localeCompare(String(a.announced_at)));
const contextLines=[];let contextLength=0;
for(const r of contextRecords.slice(0,30)){
  const line=JSON.stringify({kind:r.record_type,date:r.announced_at,title:r.title,text:r.summary,url:r.url});
  if(contextLength+line.length+1>12000)break;
  contextLines.push(line);contextLength+=line.length+1;
}
const context=contextLines.join('\n');
return [{json:{chat_id,first_name,text,command,arg,route,reply,alert_mode,hasRecords:records.length>0,context,freshness:fresh,coverage}}];

