const request = $('Parse Message & Build Reply').first().json;
let reason = 'invalid_json';
try {
  const raw = $input.first().json.text;
  if (typeof raw !== 'string' || raw.length > 6000) throw new Error('invalid_json');
  const result = JSON.parse(raw.trim().replace(/^\x60\x60\x60(?:json)?\s*/i, '').replace(/\s*\x60\x60\x60$/, ''));
  reason = 'invalid_schema';
  if (!result || typeof result !== 'object' || Array.isArray(result) ||
      Object.keys(result).sort().join(',') !== 'answer,sourceUrls' ||
      typeof result.answer !== 'string' || !result.answer.trim() ||
      result.answer.length > 900 || !Array.isArray(result.sourceUrls) ||
      result.sourceUrls.length > 2 ||
      result.sourceUrls.some(url => typeof url !== 'string') ||
      new Set(result.sourceUrls).size !== result.sourceUrls.length ||
      /https?:\/\/|www\./i.test(result.answer)) throw new Error('invalid_schema');
  const allowed = new Set();
  for (const line of String(request.context || '').split('\n')) {
    if (!line) continue;
    const record = JSON.parse(line);
    if (typeof record.url === 'string') allowed.add(record.url);
  }
  reason = 'unverified_source';
  if (result.sourceUrls.some(url => !allowed.has(url) ||
      !/^https:\/\/x\.com\/thsottiaux\/status\/\d+$/.test(url))) throw new Error('unverified_source');
  const text = [result.answer.trim(), ...result.sourceUrls].join('\n');
  reason = 'answer_too_long';
  if (text.length > 1400) throw new Error('answer_too_long');
  return [{ json: { answerValid: true, text, sourceUrls: result.sourceUrls } }];
} catch (error) {
  console.warn(JSON.stringify({event:'ai_answer_rejected',executionId:$execution.id,reason}));
  return [{ json: { answerValid: false, validationError: reason } }];
}
